mapper.select:
select c.custom_id, c.order_id, c.base_goods_id, c.custom_content, c.custom_spec, c.queue_no,
       c.queue_position, c.estimated_time, c.status, c.create_time, c.update_time, c.remark
from cl_custom_order c
inner join cl_order o on c.order_id = o.order_id and o.device_id = #{deviceId}
where c.custom_id = #{customId}

select c.custom_id, c.order_id, c.base_goods_id, c.custom_content, c.custom_spec, c.queue_no,
       c.queue_position, c.estimated_time, c.status, c.create_time, c.update_time, c.remark,
       o.order_no
from cl_custom_order c
left join cl_order o on c.order_id = o.order_id

     and c.order_id = #{orderId}
     and o.order_no like concat('%', #{orderNo}, '%')
     and c.base_goods_id = #{baseGoodsId}
     and c.status = #{status}
     and c.queue_no = #{queueNo}

order by c.create_time desc

mapper.update:
update cl_custom_order
order_id = #{orderId}, base_goods_id = #{baseGoodsId}, custom_content = #{customContent}, custom_spec = #{customSpec}, queue_no = #{queueNo}, queue_position = #{queuePosition}, estimated_time = #{estimatedTime}, status = #{status}, update_time = #{updateTime}, remark = #{remark},
where custom_id = #{customId}
